/**
 * Small 2D affine helpers for the web-native backend.
 *
 * The native animation path needs to answer one question for every animated
 * mobject: *is the motion between the start and the end state a rigid/scaling
 * affine* (translate, scale, rotate, shear) or a genuine shape morph?  An
 * affine motion can be handed to the browser as a CSS `transform`; a morph has
 * to become a crossfade (see the animation mapping).  The answer comes from a
 * least-squares fit of the start points onto the end points, which needs no
 * stored geometry: both point arrays exist for the duration of the fit only.
 */
export const IDENTITY = { a: 1, b: 0, c: 0, d: 1, tx: 0, ty: 0 };
/**
 * Fit `end ≈ M · start + t` in the least-squares sense.
 *
 * Solves the two independent 3x3 normal equations (one per output channel) with
 * a small Gaussian elimination; no numpy round-trip, and the whole thing runs in
 * O(n) over the point arrays.
 */
export function fitAffine(from, to) {
    const count = Math.min(from.length, to.length);
    if (count < 3) {
        return { matrix: translationOnly(from, to, count), residual: 0, degenerate: true };
    }
    // Normal equations for the 3-parameter model [x, y, 1] -> output.
    const ata = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    const atbx = [0, 0, 0];
    const atby = [0, 0, 0];
    for (let index = 0; index < count; index += 1) {
        const px = from[index][0] ?? 0;
        const py = from[index][1] ?? 0;
        const qx = to[index][0] ?? 0;
        const qy = to[index][1] ?? 0;
        const basis = [px, py, 1];
        for (let row = 0; row < 3; row += 1) {
            for (let col = 0; col < 3; col += 1) {
                ata[row * 3 + col] += basis[row] * basis[col];
            }
            atbx[row] += basis[row] * qx;
            atby[row] += basis[row] * qy;
        }
    }
    const solvedX = solve3(ata, atbx);
    const solvedY = solve3(ata, atby);
    if (solvedX === null || solvedY === null) {
        return { matrix: translationOnly(from, to, count), residual: 1, degenerate: true };
    }
    const matrix = {
        a: solvedX[0],
        c: solvedX[1],
        tx: solvedX[2],
        b: solvedY[0],
        d: solvedY[1],
        ty: solvedY[2],
    };
    // Residual, normalised by the target extent so it is scale-free.
    let sumSquares = 0;
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    for (let index = 0; index < count; index += 1) {
        const px = from[index][0] ?? 0;
        const py = from[index][1] ?? 0;
        const qx = to[index][0] ?? 0;
        const qy = to[index][1] ?? 0;
        const ex = matrix.a * px + matrix.c * py + matrix.tx - qx;
        const ey = matrix.b * px + matrix.d * py + matrix.ty - qy;
        sumSquares += ex * ex + ey * ey;
        minX = Math.min(minX, qx);
        maxX = Math.max(maxX, qx);
        minY = Math.min(minY, qy);
        maxY = Math.max(maxY, qy);
    }
    const extent = Math.max(maxX - minX, maxY - minY, 1e-6);
    const rms = Math.sqrt(sumSquares / count);
    return { matrix, residual: rms / extent, degenerate: false };
}
function translationOnly(from, to, count) {
    if (count === 0)
        return { ...IDENTITY };
    let sx = 0;
    let sy = 0;
    let ex = 0;
    let ey = 0;
    for (let index = 0; index < count; index += 1) {
        sx += from[index][0] ?? 0;
        sy += from[index][1] ?? 0;
        ex += to[index][0] ?? 0;
        ey += to[index][1] ?? 0;
    }
    return {
        ...IDENTITY,
        tx: ex / count - sx / count,
        ty: ey / count - sy / count,
    };
}
/** Solve a 3x3 system by Gaussian elimination with partial pivoting. */
function solve3(matrix, rhs) {
    const m = [
        [matrix[0], matrix[1], matrix[2], rhs[0]],
        [matrix[3], matrix[4], matrix[5], rhs[1]],
        [matrix[6], matrix[7], matrix[8], rhs[2]],
    ];
    for (let col = 0; col < 3; col += 1) {
        let pivot = col;
        for (let row = col + 1; row < 3; row += 1) {
            if (Math.abs(m[row][col]) > Math.abs(m[pivot][col]))
                pivot = row;
        }
        if (Math.abs(m[pivot][col]) < 1e-12)
            return null;
        if (pivot !== col) {
            const tmp = m[pivot];
            m[pivot] = m[col];
            m[col] = tmp;
        }
        const pivotRow = m[col];
        for (let row = col + 1; row < 3; row += 1) {
            const factor = m[row][col] / pivotRow[col];
            for (let k = col; k < 4; k += 1)
                m[row][k] = m[row][k] - factor * pivotRow[k];
        }
    }
    const out = [0, 0, 0];
    for (let row = 2; row >= 0; row -= 1) {
        let value = m[row][3];
        for (let col = row + 1; col < 3; col += 1)
            value -= m[row][col] * out[col];
        out[row] = value / m[row][row];
    }
    return out;
}
/**
 * Convert a world-space affine into an SVG `matrix(...)` string for an element
 * whose local coordinates are the *world-frame* vectors of the start state.
 *
 * SVG renders in a y-down viewBox while manim is y-up, so the world map is
 * conjugated by `F = diag(1, -1)`: `S = F · (M p + t) · F`.
 */
export function affineToSvgMatrix(matrix, centerX, centerY) {
    const a = matrix.a;
    const b = -matrix.b;
    const c = -matrix.c;
    const d = matrix.d;
    const e = centerX;
    const f = -centerY;
    const round = (value) => Math.round(value * 1e6) / 1e6;
    return `matrix(${round(a)}, ${round(b)}, ${round(c)}, ${round(d)}, ${round(e)}, ${round(f)})`;
}
